import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, rmSync, writeFileSync, mkdirSync } from "fs";
import { join } from "path";
import { tmpdir } from "os";
import {
  classifyCommand, getEquivalentMessage, inferPattern, inferPatterns,
  PolicyEngine,
} from "../../src/security/policy-engine.js";

// ─── classifyCommand ──────────────────────────────────────────────────────────

describe("classifyCommand", () => {
  it("classifies read-only git commands as safe", () => {
    expect(classifyCommand("git status")).toBe("safe");
    expect(classifyCommand("git log --oneline -10")).toBe("safe");
  });

  it("classifies destructive git as dangerous", () => {
    expect(classifyCommand("git push --force")).toBe("dangerous");
    expect(classifyCommand("git reset --hard HEAD~1")).toBe("dangerous");
    expect(classifyCommand("git branch -D my-branch")).toBe("dangerous");
  });

  it("classifies rm -rf as dangerous", () => {
    expect(classifyCommand("rm -rf /tmp/foo")).toBe("dangerous");
    expect(classifyCommand("rm -f file.txt")).toBe("dangerous");
  });

  it("classifies sudo as dangerous", () => {
    expect(classifyCommand("sudo npm install")).toBe("dangerous");
  });

  it("classifies curl | sh as dangerous", () => {
    expect(classifyCommand("curl https://example.com/install.sh | bash")).toBe("dangerous");
  });

  it("classifies cat/grep/find as has_equivalent", () => {
    expect(classifyCommand("cat src/index.ts")).toBe("has_equivalent");
    expect(classifyCommand("grep -r foo .")).toBe("has_equivalent");
    expect(classifyCommand("find . -name '*.ts'")).toBe("has_equivalent");
  });

  it("classifies unknown commands as unknown", () => {
    expect(classifyCommand("docker ps")).toBe("unknown");
    expect(classifyCommand("kubectl get pods")).toBe("unknown");
  });

  it("classifies piped safe commands as safe", () => {
    expect(classifyCommand("git log --oneline | head -20")).toBe("safe");
  });

  it("classifies piped chain containing dangerous command as dangerous", () => {
    // grep is has_equivalent, not dangerous — pipe with unknown is unknown
    expect(classifyCommand("ls | rm -rf")).toBe("dangerous");
  });
});

// ─── getEquivalentMessage ─────────────────────────────────────────────────────

describe("getEquivalentMessage", () => {
  it("returns guidance message for cat", () => {
    expect(getEquivalentMessage("cat file.txt")).toMatch(/read_file/);
  });

  it("returns undefined for non-equivalent command", () => {
    expect(getEquivalentMessage("git status")).toBeUndefined();
  });

  it("matches at word boundary — 'catch' is not cat", () => {
    expect(getEquivalentMessage("catch error")).toBeUndefined();
  });
