// ─── PolicyEngine ─────────────────────────────────────────────────────────────

describe("PolicyEngine.check", () => {
  let tmp: string;
  let engine: PolicyEngine;

  beforeEach(() => {
    tmp = mkdtempSync(join(tmpdir(), "policy-test-"));
    engine = new PolicyEngine(tmp);
  });

  afterEach(() => rmSync(tmp, { recursive: true, force: true }));

  it("allows read_file by default (default rule)", () => {
    const result = engine.check("read_file", { path: "src/index.ts" });
    expect(result.decision).toBe("allow");
  });

  it("asks for write_file by default", () => {
    const result = engine.check("write_file", { path: "src/foo.ts", content: "" });
    expect(result.decision).toBe("ask");
  });

  it("asks for execute_command by default", () => {
    const result = engine.check("execute_command", { command: "npm test" });
    expect(result.decision).toBe("ask");
  });

  it("auto-allows safe shell commands", () => {
    const result = engine.check("execute_command", { command: "git status" });
    expect(result.decision).toBe("allow");
  });

  it("always asks for dangerous shell commands regardless of rules", () => {
    // Add an allow rule for execute_command
    engine.addSessionRule({ tool: "execute_command", decision: "allow" });
    const result = engine.check("execute_command", { command: "rm -rf /tmp" });
    expect(result.decision).toBe("ask");
  });

  it("session rule overrides default (higher priority)", () => {
    engine.addSessionRule({ tool: "write_file", pattern: "src/**", decision: "allow" });
    const result = engine.check("write_file", { path: "src/foo.ts", content: "" });
    expect(result.decision).toBe("allow");
  });

  it("denies tool calls targeting paths outside workspace", () => {
    const result = engine.check("write_file", { path: "/etc/hosts", content: "" });
    expect(result.decision).toBe("deny");
  });

  it("denies shell commands targeting outside workspace", () => {
    const result = engine.check("execute_command", { command: `cat /etc/passwd` });
    // cat is has_equivalent → ask, but outside-workspace check should also fire
    // Result: the has_equivalent path returns "ask"; outside-workspace is separate
    // Verify workspace boundary for a non-equivalent command
    const result2 = engine.check("execute_command", { command: `ls /etc` });
    expect(result2.decision).toBe("deny");
  });

  it("persistRule saves to disk and survives reload", () => {
    engine.persistRule({ tool: "web_fetch", pattern: "https://api.example.com/*", decision: "allow" });
    // Reload from disk
    const engine2 = new PolicyEngine(tmp);
    const result = engine2.check("web_fetch", { url: "https://api.example.com/v1/data" });
    expect(result.decision).toBe("allow");
  });

  it("getRules includes default rules", () => {
    const rules = engine.getRules();
    expect(rules.some(r => r.tool === "read_file" && r.decision === "allow")).toBe(true);
  });

  it("reload drops non-session rules and re-reads from disk", () => {
    engine.addSessionRule({ tool: "write_file", decision: "allow" });
    engine.reload(); // session rules are preserved; file rules re-read
    const rules = engine.getRules();
    // Session rule should still be there after reload
    expect(rules.some(r => r.source === "session")).toBe(true);
  });
});
