import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, rmSync, existsSync, readFileSync } from "fs";
import { join } from "path";
import { tmpdir } from "os";
import { SessionBrain } from "../../src/session/brain.js";
import { EventBus } from "../../src/events/bus.js";

function makeMinimalContext(overrides?: object) {
  return {
    agent: { activePersona: "You are helpful.", activeTools: ["read_file"], boundSkills: [], skillDiscoveryIndex: [], activeMemoryIndex: [] },
    orbit: { activePlan: null, workspaceCodeMap: "", activeMemory: [], activeSkills: [] },
    drift: { focusedFiles: [], gitStatus: null },
    void: { messages: [], diagnostics: null, turnContext: [] },
    ...overrides,
  } as any;
}

describe("SessionBrain", () => {
  let tmp: string;
  let bus: EventBus;
  let brain: SessionBrain;

  beforeEach(() => {
    tmp = mkdtempSync(join(tmpdir(), "brain-test-"));
    bus = new EventBus();
    brain = new SessionBrain(tmp, "sess-001", bus);
  });

  afterEach(() => rmSync(tmp, { recursive: true, force: true }));

  it("creates session directory on construction", () => {
    expect(existsSync(join(tmp, ".voidrift", "sessions", "sess-001"))).toBe(true);
  });

  it("save writes all partition files", () => {
    const ctx = makeMinimalContext({ void: { messages: [{ role: "user", content: "hi" }], diagnostics: null, turnContext: [] } });
    brain.save(ctx, "chat");
    const dir = brain.path;
    expect(existsSync(join(dir, "system.metadata.json"))).toBe(true);
    expect(existsSync(join(dir, "work.messages.json"))).toBe(true);
    const msgs = JSON.parse(readFileSync(join(dir, "work.messages.json"), "utf-8"));
    expect(msgs).toHaveLength(1);
    expect(msgs[0].role).toBe("user");
  });

  it("load returns null when no metadata file exists", () => {
    const fresh = new SessionBrain(tmp, "nonexistent-sess", bus);
    expect(fresh.load()).toBeNull();
  });

  it("load round-trips messages and persona", () => {
    const ctx = makeMinimalContext({
      agent: { activePersona: "Be concise.", activeTools: [], boundSkills: [], skillDiscoveryIndex: [], activeMemoryIndex: [] },
      void: { messages: [{ role: "assistant", content: "Done." }], diagnostics: null, turnContext: [] },
    });
    brain.save(ctx, "chat");
    const recovered = brain.load();
    expect(recovered).not.toBeNull();
    expect(recovered!.context.agent?.activePersona).toBe("Be concise.");
    expect(recovered!.context.void?.messages).toHaveLength(1);
  });

  it("attach increments turnIndex on TURN_COMPLETE and auto-saves", () => {
    const ctx = makeMinimalContext();
    brain.attach(() => ctx, () => "chat");
    expect(brain.turn).toBe(0);
    bus.publish("TURN_COMPLETE", { turnId: "t1" });
    // Allow microtask to flush
    return new Promise(resolve => setTimeout(() => {
      expect(brain.turn).toBe(1);
      const turns = JSON.parse(readFileSync(join(brain.path, "system.turns.json"), "utf-8"));
      expect(turns).toHaveLength(1);
      expect(turns[0].agentId).toBe("chat");
      resolve(undefined);
    }, 10));
  });

  it("save preserves startTime across multiple saves", () => {
    const ctx = makeMinimalContext();
    brain.save(ctx, "chat");
    const meta1 = JSON.parse(readFileSync(join(brain.path, "system.metadata.json"), "utf-8"));
    brain.save(ctx, "chat");
    const meta2 = JSON.parse(readFileSync(join(brain.path, "system.metadata.json"), "utf-8"));
    expect(meta1.startTime).toBe(meta2.startTime);
  });

  it("listSessions returns all sessions sorted by lastActivity", () => {
    const brain2 = new SessionBrain(tmp, "sess-002", bus);
    brain.save(makeMinimalContext(), "chat");
    brain2.save(makeMinimalContext(), "chat");
    const list = brain.listSessions();
    expect(list.map(s => s.id)).toContain("sess-001");
    expect(list.map(s => s.id)).toContain("sess-002");
  });

  it("loadSession restores messages and plan from another session", () => {
    const other = new SessionBrain(tmp, "sess-other", bus);
    other.save(makeMinimalContext({
      void: { messages: [{ role: "user", content: "from other" }], diagnostics: null, turnContext: [] },
      orbit: { activePlan: "Do the thing", workspaceCodeMap: "", activeMemory: [], activeSkills: [] },
    }), "chat");

    const loaded: any = { messages: null, plan: null, diag: null };
    const ok = brain.loadSession("sess-other", {
      setMessages: (m) => { loaded.messages = m; },
      setPlan: (p) => { loaded.plan = p; },
      setDiagnostics: (d) => { loaded.diag = d; },
    });
    expect(ok).toBe(true);
    expect(loaded.messages[0].content).toBe("from other");
    expect(loaded.plan).toBe("Do the thing");
  });

  it("loadSession returns false for non-existent session", () => {
    const ok = brain.loadSession("does-not-exist", { setMessages: () => {}, setPlan: () => {}, setDiagnostics: () => {} });
    expect(ok).toBe(false);
  });
});
