    pm.add("task-a", "Now task", "", "now");
    pm.add("task-b", "Later task", "", "later");
    pm.add("task-c", "Next task", "", "next");
    expect(pm.byPriority("now")).toHaveLength(1);
    expect(pm.byPriority("later")).toHaveLength(1);
    expect(pm.byPriority("next")).toHaveLength(1);
  });

