    pm.add("task-a", "Later task", "", "later");
    expect(pm.compile()).toBeNull();
  });

  it("compile formats 'now' items with rationale", () => {
    pm.add("task-a", "Build auth", "Legal requirement", "now");
    const compiled = pm.compile();
    expect(compiled).toContain("Build auth");
    expect(compiled).toContain("Legal requirement");
    expect(compiled).toContain("--- Active Plan ---");
  });

  it("compile omits rationale when empty", () => {
    pm.add("task-a", "Build auth", "", "now");
    const compiled = pm.compile();
    expect(compiled).not.toContain(" — ");
  });

  it("updatePriority changes priority and persists", () => {
    pm.add("task-a", "Some task", "", "now");
    const ok = pm.updatePriority("task-a.md", "later");
    expect(ok).toBe(true);
    expect(pm.get("task-a.md")!.priority).toBe("later");
  });

  it("updatePriority returns false for nonexistent file", () => {
    expect(pm.updatePriority("ghost.md", "now")).toBe(false);
  });

  it("remove deletes the file", () => {
    pm.add("task-a", "Task", "", "now");
    expect(pm.all()).toHaveLength(1);
