import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, rmSync, writeFileSync, mkdirSync } from "fs";
import { join } from "path";
import { tmpdir } from "os";
import { computeDiff, computeEditDiff } from "../../src/safeguards/diff.js";

describe("computeDiff", () => {
  let tmp: string;

  beforeEach(() => { tmp = mkdtempSync(join(tmpdir(), "diff-test-")); });
  afterEach(() => rmSync(tmp, { recursive: true, force: true }));

  it("treats all lines as additions for a new file", () => {
    const lines = computeDiff(tmp, "newfile.ts", "line1\nline2");
    expect(lines).toEqual(["+line1", "+line2"]);
  });

  it("returns header + unchanged lines for identical content", () => {
    writeFileSync(join(tmp, "same.ts"), "hello\nworld");
    const lines = computeDiff(tmp, "same.ts", "hello\nworld");
    expect(lines.some(l => l.startsWith("---"))).toBe(true);
    expect(lines.some(l => l.startsWith("+"))).toBe(false); // no additions
    expect(lines.some(l => l.startsWith("-"))).toBe(false); // no removals
  });

  it("shows - for removed lines and + for added lines", () => {
    writeFileSync(join(tmp, "edit.ts"), "line1\nold line\nline3");
    const lines = computeDiff(tmp, "edit.ts", "line1\nnew line\nline3");
    expect(lines).toContain("-old line");
    expect(lines).toContain("+new line");
  });

  it("handles content that is shorter than the original", () => {
    writeFileSync(join(tmp, "shrink.ts"), "a\nb\nc");
    const lines = computeDiff(tmp, "shrink.ts", "a\nb");
    expect(lines).toContain("-c");
  });

  it("handles content that is longer than the original", () => {
    writeFileSync(join(tmp, "grow.ts"), "a\nb");
    const lines = computeDiff(tmp, "grow.ts", "a\nb\nc");
    expect(lines).toContain("+c");
  });
});

describe("computeEditDiff", () => {
  let tmp: string;

  beforeEach(() => { tmp = mkdtempSync(join(tmpdir(), "editdiff-test-")); });
  afterEach(() => rmSync(tmp, { recursive: true, force: true }));

  it("returns file-not-found error for missing file", () => {
    const lines = computeEditDiff(tmp, "ghost.ts", "old", "new");
    expect(lines[0]).toContain("File not found");
  });

  it("returns search-not-found error when search block is absent", () => {
    writeFileSync(join(tmp, "file.ts"), "content here");
    const lines = computeEditDiff(tmp, "file.ts", "not present", "replacement");
    expect(lines[0]).toContain("Search block not found");
  });

  it("shows removed lines prefixed with - and additions with +", () => {
    writeFileSync(join(tmp, "file.ts"), "const a = 1;\nconst b = 2;");
    const lines = computeEditDiff(tmp, "file.ts", "const a = 1;", "const a = 42;");
    expect(lines).toContain("-const a = 1;");
    expect(lines).toContain("+const a = 42;");
  });

  it("includes --- and +++ headers", () => {
    writeFileSync(join(tmp, "file.ts"), "x");
    const lines = computeEditDiff(tmp, "file.ts", "x", "y");
    expect(lines[0]).toMatch(/^--- /);
    expect(lines[1]).toMatch(/^\+\+\+ /);
  });
});
