import { describe, it, expect } from "vitest";
import { validateAssets } from "../../src/bootstrap/validate.js";

function makeAgents(ids: string[]) {
  return {
    listInteractive: () => ids.slice(0, Math.ceil(ids.length / 2)).map(id => ({ id })),
    listTask: () => ids.slice(Math.ceil(ids.length / 2)).map(id => ({ id })),
  } as any;
}

function makeSkills(skills: Array<{ name?: string; description?: string; agents: string[]; filePath: string }>) {
  return {
    indexed: skills.map(s => ({
      name: s.name ?? "test-skill",
      description: s.description ?? "A skill",
      agents: s.agents,
      filePath: s.filePath,
    })),
  } as any;
}

describe("validateAssets", () => {
  it("returns no issues for valid skills with known agents", () => {
    const agents = makeAgents(["chat", "plan"]);
    const skills = makeSkills([{ agents: ["chat"], filePath: "/tmp/skill.md" }]);
    // filePath doesn't exist so frontmatter check is skipped (caught) — no issue for missing fs
    const issues = validateAssets(agents, skills);
    expect(issues.filter(i => i.type === "skill" && i.message.includes("nonexistent"))).toHaveLength(0);
  });

  it("reports error for skill missing name", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([{ name: "", description: "A skill", agents: [], filePath: "/tmp/x.md" }]);
    const issues = validateAssets(agents, skills);
    expect(issues.some(i => i.message.includes("Missing required name"))).toBe(true);
  });

  it("reports error for skill missing description", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([{ name: "my-skill", description: "", agents: [], filePath: "/tmp/x.md" }]);
    const issues = validateAssets(agents, skills);
    expect(issues.some(i => i.message.includes("Missing required name"))).toBe(true);
  });

  it("reports dangling agent reference", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([{ agents: ["nonexistent-agent"], filePath: "/tmp/x.md" }]);
    const issues = validateAssets(agents, skills);
    expect(issues.some(i => i.message.includes("nonexistent-agent"))).toBe(true);
  });

  it("reports multiple dangling agents in one skill", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([{ agents: ["ghost-a", "ghost-b"], filePath: "/tmp/x.md" }]);
    const issues = validateAssets(agents, skills);
    const issue = issues.find(i => i.message.includes("References nonexistent"));
    expect(issue?.message).toContain("ghost-a");
    expect(issue?.message).toContain("ghost-b");
  });

  it("returns empty array when skills list is empty", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([]);
    expect(validateAssets(agents, skills)).toEqual([]);
  });
});
