import { describe, it, expect } from "vitest";
import { validateAssets } from "../../src/bootstrap/validate.js";

function makeAgents(ids: string[]) {
  return {
    listInteractive: () => ids.slice(0, Math.ceil(ids.length / 2)).map(id => ({ id })),
    listTask: () => ids.slice(Math.ceil(ids.length / 2)).map(id => ({ id })),
  } as any;
}

function makeSkills(skills: Array<{ name?: string; description?: string; agents: string[]; filePath: string }>) {
  return {
    indexed: skills.map(s => ({
      name: s.name ?? "test-skill",
      description: s.description ?? "A skill",
      agents: s.agents,
      filePath: s.filePath,
    })),
  } as any;
}

describe("validateAssets", () => {
  it("returns no issues for valid skills with known agents", () => {
    const agents = makeAgents(["chat", "plan"]);
    const skills = makeSkills([{ agents: ["chat"], filePath: "/tmp/skill.md" }]);
    // filePath doesn't exist so frontmatter check is skipped (caught) — no issue for missing fs
    const issues = validateAssets(agents, skills);
    expect(issues.filter(i => i.type === "skill" && i.message.includes("nonexistent"))).toHaveLength(0);
  });

  it("reports error for skill missing name", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([{ name: "", description: "A skill", agents: [], filePath: "/tmp/x.md" }]);
    const issues = validateAssets(agents, skills);
    expect(issues.some(i => i.message.includes("Missing required name"))).toBe(true);
  });

  it("reports error for skill missing description", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([{ name: "my-skill", description: "", agents: [], filePath: "/tmp/x.md" }]);
    const issues = validateAssets(agents, skills);
    expect(issues.some(i => i.message.includes("Missing required name"))).toBe(true);
  });

  it("reports dangling agent reference", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([{ agents: ["nonexistent-agent"], filePath: "/tmp/x.md" }]);
    const issues = validateAssets(agents, skills);
    expect(issues.some(i => i.message.includes("nonexistent-agent"))).toBe(true);
  });

  it("reports multiple dangling agents in one skill", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([{ agents: ["ghost-a", "ghost-b"], filePath: "/tmp/x.md" }]);
    const issues = validateAssets(agents, skills);
    const issue = issues.find(i => i.message.includes("References nonexistent"));
    expect(issue?.message).toContain("ghost-a");
    expect(issue?.message).toContain("ghost-b");
  });

  it("returns empty array when skills list is empty", () => {
    const agents = makeAgents(["chat"]);
    const skills = makeSkills([]);
    expect(validateAssets(agents, skills)).toEqual([]);
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import { StatsTracker } from "../../src/session/stats.js";

describe("StatsTracker", () => {
  let tracker: StatsTracker;

  beforeEach(() => { tracker = new StatsTracker("sess-abc"); });

  it("initializes with zero turns and tools", () => {
    const s = tracker.current;
    expect(s.turns).toBe(0);
    expect(s.tools.total).toBe(0);
  });

  it("recordTurn increments global turn count", () => {
    tracker.recordTurn("gpt-4", 100, 50, 0, 1000);
    expect(tracker.current.turns).toBe(1);
  });

  it("recordTurn accumulates per-model token counts", () => {
    tracker.recordTurn("gpt-4", 100, 50, 10, 800);
    tracker.recordTurn("gpt-4", 200, 100, 20, 600);
    const usage = tracker.current.modelUsage.get("gpt-4")!;
    expect(usage.inputTokens).toBe(300);
    expect(usage.outputTokens).toBe(150);
    expect(usage.cacheTokens).toBe(30);
    expect(usage.turns).toBe(2);
  });

  it("recordTurn tracks separate models independently", () => {
    tracker.recordTurn("model-a", 50, 25, 0, 500);
    tracker.recordTurn("model-b", 80, 40, 0, 700);
    expect(tracker.current.modelUsage.has("model-a")).toBe(true);
    expect(tracker.current.modelUsage.has("model-b")).toBe(true);
    expect(tracker.current.modelUsage.get("model-a")!.inputTokens).toBe(50);
  });

  it("recordToolCall tracks success and failure counts", () => {
    tracker.recordToolCall(true, 100);
    tracker.recordToolCall(true, 200);
    tracker.recordToolCall(false, 50);
    expect(tracker.current.tools.total).toBe(3);
    expect(tracker.current.tools.success).toBe(2);
    expect(tracker.current.tools.failed).toBe(1);
  });

  it("recordToolCall accumulates timing", () => {
    tracker.recordToolCall(true, 100);
    tracker.recordToolCall(false, 200);
    expect(tracker.current.tools.totalTimeMs).toBe(300);
  });

  it("durationFormatted returns seconds for short sessions", () => {
    // durationMs is based on Date.now() — just check it's a string with 's'
    expect(tracker.durationFormatted).toMatch(/s$/);
  });

  it("durationFormatted formats minutes correctly", () => {
    // Fake startedAt by monkey-patching via current
    (tracker as any).stats.startedAt = Date.now() - 125_000; // 2m 5s ago
    expect(tracker.durationFormatted).toMatch(/^2m/);
  });

  it("durationFormatted formats hours correctly", () => {
    (tracker as any).stats.startedAt = Date.now() - 7_300_000; // ~2h 1m
    expect(tracker.durationFormatted).toMatch(/^2h/);
  });
});

